"""Asteroid Collision — stack simulation.

Only a right-moving asteroid on the stack can collide with an incoming
left-moving one, so the stack holds the survivors so far.

Time: O(n)   Space: O(n)
"""
from typing import List


class Solution:
    def asteroidCollision(self, asteroids: List[int]) -> List[int]:
        stack = []
        for asteroid in asteroids:
            alive = True
            while alive and asteroid < 0 and stack and stack[-1] > 0:
                if stack[-1] < -asteroid:
                    stack.pop()          # the one on the stack explodes
                elif stack[-1] == -asteroid:
                    stack.pop()          # both explode
                    alive = False
                else:
                    alive = False        # the incoming one explodes
            if alive:
                stack.append(asteroid)
        return stack
